action.code:
// Initialize the start node
    start_node_->visited = true;
    start_node_->g_value = 0.0f;
    start_node_->h_value = calc_h_value(start_node_);
    open_list_.push_back(start_node_);

    // Main A* loop
    while (!open_list_.empty()) {
        RouteModel::Node* current_node = next_node();

        // Goal check
        if (current_node == end_node_) {
            // Build the final path and store it in the model
            m_model_.path = construct_final_path(current_node);
            return;
        }

        // Expand the current node
        add_neighbors(current_node);
    }

